simple.c:
int add(int a, int b) {
    return a + b;
}

complex.c:
long calc(long a, long b, long c, long d,
          long e, long f, long g, long h) {
    return a*b + c*d + e*f + g*h;
}

variadic.c:
int sum_ints(int count, ...) {
    va_list ap;
    va_start(ap, count);
    int total = 0;
    for (int i = 0; i < count; i++)
        total += va_arg(ap, int);
    va_end(ap);
    return total;
}
